D)*1)%11=0 THEN ('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9))||((10-((CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),1,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),1,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),2,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),2,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),3,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),3,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),4,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),4,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),5,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),5,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),6,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),6,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),7,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),7,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),8,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),8,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),9,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),9,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),10,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),10,1)::int END)*3+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),11,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),11,1)::int END)*1+(CASE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),12,1) WHEN 'X' THEN 10 ELSE substring(('978'||left(upper(regexp_replace(coalesce(e.isbn,''),E'[\\s-]','','g')),9)),12,1)::int END)*3)%10)%10)::text END END)
 AND proof->>'locale'=e.locale AND nullif(e.locale,'') IS NOT NULL AND proof->>'edition_title'=e.title AND nullif(btrim(e.title),'') IS NOT NULL
 AND proof->>'reason' IN (E'children_picture',E'children_only',E'graded_reader',E'abridged',E'non_reading_product',E'wrong_locale',E'wrong_work',E'editorial_exclusion')
 AND (proof->>'reason' NOT IN (E'wrong_work',E'editorial_exclusion') OR (jsonb_typeof(proof->'content_id')='string' AND nullif(proof->>'content_id','')=e.content_id))
 AND char_length(btrim(coalesce(proof->>'explanation','')))>=20
 AND coalesce(proof->>'source_url','') ~ '^https://[A-Za-z0-9.-]*[A-Za-z][A-Za-z0-9-]*[.]?(:[0-9]{1,5})?([/?#][^[:space:]]*)?$'
 AND (CASE WHEN proof->>'source_url' ~ '^https://[A-Za-z0-9.-]+:[0-9]{1,5}([/?#]|$)' THEN substring(proof->>'source_url' from '^https://[^/?#:]+:([0-9]+)')::int ELSE 0 END)<=65535
 AND lower(split_part(split_part(substring(proof->>'source_url' from '^https://([^/?#]+)'),':',1),'@',1)) !~ '(^|[.])openlibrary[.]org[.]?$')),false)
   AND public.book_translator_identity(e.sources->'translators') IS NOT DISTINCT FROM translators
 ) THEN RAISE EXCEPTION 'Same original or translation already has a representative edition; attach products to it'; END IF;
 RETURN new;
END;
$policy$;
COMMIT;
